/**
 * Render worker/src/openapi-spec.ts from the built document.
 *
 * Shared by the generator (`pnpm run gen:worker`) and openapi-spec-verify.ts.
 */
export function renderSpec(spec: string): string {
  return `/**
 * GENERATED by \`pnpm run gen:worker\` from openapi-builder.ts — do not edit by
 * hand. openapi-spec-verify.ts fails when this drifts from the live schemas.
 *
 * The exact bytes GET /task/api/openapi.json answers with. Building them per
 * request cost 90–250 ms of CPU and loaded every route group (#103); the
 * document is a pure function of the source, so it is built once, here.
 */
export const OPENAPI_SPEC = ${JSON.stringify(spec)}
`
}
